private fun datafusionSettings0(): List<SettingDef> = listOf(
    SettingDef("datafusion.explain.tree_maximum_render_width", description = "(format=tree only) Maximum total width of the rendered tree. When set to 0, the tree will have no width limit."),
    SettingDef("datafusion.execution.parquet.force_filter_selections", description = "(reading) Force the use of RowSelections for filter results, when pushdown_filters is enabled. If false, the reader will automatically choose between a RowSelection and a Bitmap based on the number and pattern of selected rows."),
    SettingDef("datafusion.execution.parquet.metadata_size_hint", description = "(reading) If specified, the parquet reader will try and fetch the last `size_hint` bytes of the parquet file optimistically. If not specified, two reads are required: One read to fetch the 8-byte parquet footer and another to fetch the metadata length encoded in the footer Default setting to 512 KiB, which should be sufficient for most parquet files, it can reduce one I/O operation per parquet file. If the metadata is larger than the hint, two reads will still be performed."),
    SettingDef("datafusion.execution.parquet.pushdown_filters", description = "(reading) If true, filter expressions are be applied during the parquet decoding operation to reduce the number of rows decoded. This optimization is sometimes called \"late materialization\"."),
    SettingDef("datafusion.execution.parquet.reorder_filters", description = "(reading) If true, filter expressions evaluated during the parquet decoding operation will be reordered heuristically to minimize the cost of evaluation. If false, the filters are applied in the same order as written in the query"),
    SettingDef("datafusion.execution.parquet.binary_as_string", description = "(reading) If true, parquet reader will read columns of `Binary/LargeBinary` with `Utf8`, and `BinaryView` with `Utf8View`. Parquet files generated by some legacy writers do not correctly set the UTF8 flag for strings, causing string columns to be loaded as BLOB instead."),
    SettingDef("datafusion.execution.parquet.schema_force_view_types", description = "(reading) If true, parquet reader will read columns of `Utf8/Utf8Large` with `Utf8View`, and `Binary/BinaryLarge` with `BinaryView`."),
    SettingDef("datafusion.execution.parquet.coerce_int96", description = "(reading) If true, parquet reader will read columns of physical type int96 as originating from a different resolution than nanosecond. This is useful for reading data from systems like Spark which stores microsecond resolution timestamps in an int96 allowing it to write values with a larger date range than 64-bit timestamps with nanosecond resolution."),
    SettingDef("datafusion.execution.parquet.enable_page_index", description = "(reading) If true, reads the Parquet data page level metadata (the Page Index), if present, to reduce the I/O and number of rows decoded."),
    SettingDef("datafusion.execution.parquet.pruning", description = "(reading) If true, the parquet reader attempts to skip entire row groups based on the predicate in the query and the metadata (min/max values) stored in the parquet file"),
    SettingDef("datafusion.execution.parquet.skip_metadata", description = "(reading) If true, the parquet reader skip the optional embedded metadata that may be in the file Schema. This setting can help avoid schema conflicts when querying multiple parquet files with schemas containing compatible types but different metadata"),
    SettingDef("datafusion.execution.parquet.coerce_int96_tz", description = "(reading) Optional timezone applied to INT96 columns when `coerce_int96` is set. When `Some`, INT96 columns coerce to `Timestamp(<coerce_int96>, Some(<tz>))` instead of the default `Timestamp(<coerce_int96>, None)`. Spark and other systems write INT96 values as UTC-adjusted instants, so callers that need the resulting Arrow type to be timezone-aware (e.g. for Spark `TimestampType` semantics) should set this to `\"UTC\"`. No effect when `coerce_int96` is `None`."),
    SettingDef("datafusion.execution.parquet.max_predicate_cache_size", description = "(reading) The maximum predicate cache size, in bytes. When `pushdown_filters` is enabled, sets the maximum memory used to cache the results of predicate evaluation between filter evaluation and output generation. Decreasing this value will reduce memory usage, but may increase IO and CPU usage. None means use the default parquet reader setting. 0 means no caching."),
    SettingDef("datafusion.execution.parquet.bloom_filter_on_read", description = "(reading) Use any available bloom filters when reading parquet files"),
    SettingDef("datafusion.execution.parquet.encoding", description = "(writing)  Sets default encoding for any column. Valid values are: plain, plain_dictionary, rle, bit_packed, delta_binary_packed, delta_length_byte_array, delta_byte_array, rle_dictionary, and byte_stream_split. These values are not case sensitive. If NULL, uses default parquet writer setting"),
    SettingDef("datafusion.execution.parquet.maximum_buffered_record_batches_per_stream", description = "(writing) By default parallel parquet writer is tuned for minimum memory usage in a streaming execution plan. You may see a performance benefit when writing large parquet files by increasing maximum_parallel_row_group_writers and maximum_buffered_record_batches_per_stream if your system has idle cores and can tolerate additional memory usage. Boosting these values is likely worthwhile when writing out already in-memory data, such as from a cached data frame."),
    SettingDef("datafusion.execution.parquet.maximum_parallel_row_group_writers", description = "(writing) By default parallel parquet writer is tuned for minimum memory usage in a streaming execution plan. You may see a performance benefit when writing large parquet files by increasing maximum_parallel_row_group_writers and maximum_buffered_record_batches_per_stream if your system has idle cores and can tolerate additional memory usage. Boosting these values is likely worthwhile when writing out already in-memory data, such as from a cached data frame."),
    SettingDef("datafusion.execution.parquet.allow_single_file_parallelism", description = "(writing) Controls whether DataFusion will attempt to speed up writing parquet files by serializing them in parallel. Each column in each row group in each output file are serialized in parallel leveraging a maximum possible core count of n_files*n_row_groups*n_columns."),
    SettingDef("datafusion.execution.parquet.content_defined_chunking.enabled", description = "(writing) EXPERIMENTAL: Enable content-defined chunking (CDC) when writing parquet files. When enabled, parallel writing is automatically disabled since the chunker state must persist across row groups."),
    SettingDef("datafusion.execution.parquet.created_by", description = "(writing) Sets \"created by\" property"),
    SettingDef("datafusion.execution.parquet.dictionary_page_size_limit", description = "(writing) Sets best effort maximum dictionary page size, in bytes"),
    SettingDef("datafusion.execution.parquet.data_page_row_count_limit", description = "(writing) Sets best effort maximum number of rows in data page"),
    SettingDef("datafusion.execution.parquet.data_pagesize_limit", description = "(writing) Sets best effort maximum size of data page in bytes"),
    SettingDef("datafusion.execution.parquet.bloom_filter_fpp", description = "(writing) Sets bloom filter false positive probability. If NULL, uses default parquet writer setting"),
    SettingDef("datafusion.execution.parquet.bloom_filter_ndv", description = "(writing) Sets bloom filter number of distinct values. If NULL, uses default parquet writer setting"),
    SettingDef("datafusion.execution.parquet.column_index_truncate_length", description = "(writing) Sets column index truncate length"),
    SettingDef("datafusion.execution.parquet.compression", description = "(writing) Sets default parquet compression codec. Valid values are: uncompressed, snappy, gzip(level), brotli(level), lz4, zstd(level), and lz4_raw. These values are not case sensitive. If NULL, uses default parquet writer setting Note that this default setting is not the same as the default parquet writer setting."),
    SettingDef("datafusion.execution.parquet.dictionary_enabled", description = "(writing) Sets if dictionary encoding is enabled. If NULL, uses default parquet writer setting"),
    SettingDef("datafusion.execution.parquet.statistics_enabled", description = "(writing) Sets if statistics are enabled for any column Valid values are: \"none\", \"chunk\", and \"page\" These values are not case sensitive. If NULL, uses default parquet writer setting"),
    SettingDef("datafusion.execution.parquet.writer_version", description = "(writing) Sets parquet writer version valid values are \"1.0\" and \"2.0\""),
    SettingDef("datafusion.execution.parquet.statistics_truncate_length", description = "(writing) Sets statistics truncate length. If NULL, uses default parquet writer setting"),
    SettingDef("datafusion.execution.parquet.write_batch_size", description = "(writing) Sets write_batch_size in rows"),
    SettingDef("datafusion.execution.parquet.skip_arrow_metadata", description = "(writing) Skip encoding the embedded arrow metadata in the KV_meta This is analogous to the `ArrowWriterOptions::with_skip_arrow_metadata`. Refer to <https://docs.rs/parquet/53.3.0/parquet/arrow/arrow_writer/struct.ArrowWriterOptions.html#method.with_skip_arrow_metadata>"),
    SettingDef("datafusion.execution.parquet.max_row_group_size", description = "(writing) Target maximum number of rows in each row group (defaults to 1M rows). Writing larger row groups requires more memory to write, but can get better compression and be faster to read. When `max_row_group_bytes` is also set, the writer flushes a row group when either limit is reached, whichever comes first."),
    SettingDef("datafusion.execution.parquet.max_row_group_bytes", description = "(writing) Target maximum size of each row group in bytes. When set, the writer flushes whenever either this limit or `max_row_group_size` is reached, whichever comes first. Useful for bounding writer memory on wide schemas where a row-count limit can map to very different byte sizes. Matches the behavior of `parquet.block.size` in parquet-mr. If `None` (the default), only the row-count limit applies. Currently only honored when `allow_single_file_parallelism` is `false`; by default the parallel file writer ignores this limit."),
    SettingDef("datafusion.execution.parquet.bloom_filter_on_write", description = "(writing) Write bloom filters for all columns when creating parquet files"),
    SettingDef("datafusion.execution.perfect_hash_join_small_build_threshold", description = "A perfect hash join (see `HashJoinExec` for more details) will be considered if the range of keys (max - min) on the build side is < this threshold. This provides a fast path for joins with very small key ranges, bypassing the density check. Currently only supports cases where build_side.num_rows() < u32::MAX. Support for build_side.num_rows() >= u32::MAX will be added in the future."),
    SettingDef("datafusion.execution.skip_partial_aggregation_probe_ratio_threshold", description = "Aggregation ratio (number of distinct groups / number of input rows) threshold for skipping partial aggregation. If the value is greater then partial aggregation will skip aggregation for further input"),
    SettingDef("datafusion.execution.split_file_groups_by_statistics", description = "Attempt to eliminate sorts by packing & sorting files with non-overlapping statistics into the same file groups. Currently experimental"),
    SettingDef("datafusion.sql_parser.dialect", description = "Configure the SQL dialect used by DataFusion's parser; supported values include: Generic, MySQL, PostgreSQL, Hive, SQLite, Snowflake, Redshift, MsSQL, ClickHouse, BigQuery, Ansi, DuckDB, Databricks, Spark."),
)

private fun datafusionSettings1(): List<SettingDef> = listOf(
    SettingDef("datafusion.format.date_format", description = "Date format for date arrays"),
    SettingDef("datafusion.execution.batch_size", description = "Default batch size while creating new batches, it's especially useful for buffer-in-memory batches since creating tiny batches would result in too much metadata memory consumption"),
    SettingDef("datafusion.catalog.has_header", description = "Default value for `format.has_header` for `CREATE EXTERNAL TABLE` if not specified explicitly in the statement."),
    SettingDef("datafusion.explain.format", description = "Display format of explain. Default is \"indent\". When set to \"tree\", it will print the plan in a tree-rendered format."),
    SettingDef("datafusion.format.duration_format", description = "Duration format. Can be either `\"pretty\"` or `\"ISO8601\"`"),
    SettingDef("datafusion.optimizer.enable_sort_pushdown", description = "Enable sort pushdown optimization. When enabled, attempts to push sort requirements down to data sources that can natively handle them (e.g., by reversing file/row group read order). Returns **inexact ordering**: Sort operator is kept for correctness, but optimized input enables early termination for TopK queries (ORDER BY ... LIMIT N), providing significant speedup. Memory: No additional overhead (only changes read order). Future: Will add option to detect perfectly sorted data and eliminate Sort completely. Default: true"),
    SettingDef("datafusion.execution.planning_concurrency", description = "Fan-out during initial physical planning. This is mostly use to plan `UNION` children in parallel. Defaults to the number of CPU cores on the system"),
    SettingDef("datafusion.format.datetime_format", description = "Format for DateTime arrays"),
    SettingDef("datafusion.format.null", description = "Format string for nulls"),
    SettingDef("datafusion.execution.minimum_parallel_output_files", description = "Guarantees a minimum level of output files running in parallel. RecordBatches will be distributed in round robin fashion to each parallel writer. Each writer is closed and a new file opened once soft_max_rows_per_output_file is reached."),
    SettingDef("datafusion.execution.hash_join_buffering_capacity", description = "How many bytes to buffer in the probe side of hash joins while the build side is concurrently being built. Without this, hash joins will wait until the full materialization of the build side before polling the probe side. This is useful in scenarios where the query is not completely CPU bounded, allowing to do some early work concurrently and reducing the latency of the query. Note that when hash join buffering is enabled, the probe side will start eagerly polling data, not giving time for the producer side of dynamic filters to produce any meaningful predicate. Queries with dynamic filters might see performance degradation. Disabled by default, set to a number greater than 0 for enabling it."),
    SettingDef("datafusion.format.safe", description = "If set to `true` any formatting errors will be written to the output instead of being converted into a [`std::fmt::Error`]"),
    SettingDef("datafusion.sql_parser.support_varchar_with_length", description = "If true, permit lengths for `VARCHAR` such as `VARCHAR(20)`, but ignore the length. If false, error if a `VARCHAR` with a length is specified. The Arrow type system does not have a notion of maximum string length and thus DataFusion can not enforce such limits."),
    SettingDef("datafusion.sql_parser.map_string_types_to_utf8view", description = "If true, string types (VARCHAR, CHAR, Text, and String) are mapped to `Utf8View` during SQL planning. If false, they are mapped to `Utf8`. Default is true."),
    SettingDef("datafusion.catalog.location", description = "Location scanned to load tables for `default` schema"),
    SettingDef("datafusion.execution.sort_pushdown_buffer_capacity", description = "Maximum buffer capacity (in bytes) per partition for BufferExec inserted during sort pushdown optimization. When PushdownSort eliminates a SortExec under SortPreservingMergeExec, a BufferExec is inserted to replace SortExec's buffering role. This prevents I/O stalls by allowing the scan to run ahead of the merge. This uses strictly less memory than the SortExec it replaces (which buffers the entire partition). The buffer respects the global memory pool limit. Setting this to a large value is safe — actual memory usage is bounded by partition size and global memory limits."),
    SettingDef("datafusion.execution.parquet.content_defined_chunking.max_chunk_size", description = "Maximum chunk size in bytes. A split is forced when the accumulated size exceeds this value. Default is 1 MiB."),
    SettingDef("datafusion.runtime.memory_limit", description = "Maximum memory limit for query execution. Supports suffixes K (kilobytes), M (megabytes), and G (gigabytes) or '0' for 0. Example: '2G' for 2 gigabytes."),
    SettingDef("datafusion.runtime.metadata_cache_limit", description = "Maximum memory to use for file metadata cache such as Parquet metadata. Supports suffixes K (kilobytes), M (megabytes), and G (gigabytes) or '0' for 0. Example: '2G' for 2 gigabytes."),
    SettingDef("datafusion.runtime.file_statistics_cache_limit", description = "Maximum memory to use for file statistics cache. Supports suffixes K (kilobytes), M (megabytes), and G (gigabytes) or '0' for 0. Example: '2G' for 2 gigabytes."),
    SettingDef("datafusion.runtime.list_files_cache_limit", description = "Maximum memory to use for list files cache. Supports suffixes K (kilobytes), M (megabytes), and G (gigabytes) or '0' for 0. Example: '2G' for 2 gigabytes."),
    SettingDef("datafusion.optimizer.hash_join_inlist_pushdown_max_distinct_values", description = "Maximum number of distinct values (rows) in the build side of a hash join to be pushed down as an InList expression for dynamic filtering. Build sides with more rows than this will use hash table lookups instead. Set to 0 to always use hash table lookups. This provides an additional limit beyond `hash_join_inlist_pushdown_max_size` to prevent very large IN lists that might not provide much benefit over hash table lookups. This uses the deduplicated row count once the build side has been evaluated. The default is 150 values per partition. This is inspired by Trino's `max-filter-keys-per-column` setting. See: <https://trino.io/docs/current/admin/dynamic-filtering.html#dynamic-filter-collection-thresholds>"),
    SettingDef("datafusion.runtime.max_spill_merge_fan_in", description = "Maximum number of spill files opened by one external merge pass. Use 0 for unlimited. Values below 2 still use 2 so a merge can make progress."),
    SettingDef("datafusion.execution.parquet.max_in_list_size", description = "Maximum number of values in an `IN (...)` list for which pruning will occur. Longer lists will not be used to prune files, row groups, or data pages. Higher values help in cases such as filtering on a list of ~25-100 identifiers, but also make the predicate more expensive to evaluate. Set to 0 to disable `IN (...)` list pruning entirely. Defaults to 20."),
    SettingDef("datafusion.execution.max_spill_file_size_bytes", description = "Maximum size in bytes for individual spill files before rotating to a new file. When operators spill data to disk (e.g., RepartitionExec), they write multiple batches to the same file until this size limit is reached, then rotate to a new file. This reduces syscall overhead compared to one-file-per-batch while preventing files from growing too large. A larger value reduces file creation overhead but may hold more disk space. A smaller value creates more files but allows finer-grained space reclamation as files can be deleted once fully consumed. Now only `RepartitionExec` supports this spill file rotation feature, other spilling operators may create spill files larger than the limit. Default: 128 MB"),
    SettingDef("datafusion.optimizer.hash_join_inlist_pushdown_max_size", description = "Maximum size in bytes for the build side of a hash join to be pushed down as an InList expression for dynamic filtering. Build sides larger than this will use hash table lookups instead. Set to 0 to always use hash table lookups. InList pushdown can be more efficient for small build sides because it can result in better statistics pruning as well as use any bloom filters present on the scan side. InList expressions are also more transparent and easier to serialize over the network in distributed uses of DataFusion. On the other hand InList pushdown requires making a copy of the data and thus adds some overhead to the build side and uses more memory. This setting is per-partition, so we may end up using `hash_join_inlist_pushdown_max_size` * `target_partitions` memory. The default is 128kB per partition. This should allow point lookup joins (e.g. joining on a unique primary key) to use InList pushdown in most cases but avoids excessive memory usage or overhead for larger joins."),
    SettingDef("datafusion.runtime.max_temp_directory_size", description = "Maximum temporary file directory size. Supports suffixes K (kilobytes), M (megabytes), and G (gigabytes) or '0' for 0. Example: '2G' for 2 gigabytes."),
    SettingDef("datafusion.execution.parquet.content_defined_chunking.min_chunk_size", description = "Minimum chunk size in bytes. The rolling hash will not trigger a split until this many bytes have been accumulated. Default is 256 KiB."),
    SettingDef("datafusion.optimizer.preserve_file_partitions", description = "Minimum number of distinct partition values required to group files by their Hive partition column values (enabling output partitioning declaration). How the option is used:     - preserve_file_partitions=0: Disable it.     - preserve_file_partitions=1: Always enable it.     - preserve_file_partitions=N, actual file partitions=M: Only enable when M >= N.     This threshold preserves I/O parallelism when file partitioning is below it. Note: This may reduce parallelism, rooting from the I/O level, if the number of distinct partitions is less than the target_partitions."),
    SettingDef("datafusion.optimizer.repartition_file_min_size", description = "Minimum total file size in bytes for file-group byte-range splitting to fire. Files (or merged file groups) smaller than this stay as one partition. Lower values produce more, smaller partitions — better at filling `target_partitions` worth of cores when files are modestly sized, at the cost of slightly more per-partition open / metadata-load overhead."),
    SettingDef("datafusion.execution.parquet.content_defined_chunking.norm_level", description = "Normalization level. Increasing this improves deduplication ratio but increases fragmentation. Recommended range is [-3, 3], default is 0."),
    SettingDef("datafusion.execution.meta_fetch_concurrency", description = "Number of files to read in parallel when inferring schema and statistics"),
    SettingDef("datafusion.execution.skip_partial_aggregation_probe_rows_threshold", description = "Number of input rows partial aggregation partition should process, before aggregation ratio check and trying to switch to skipping aggregation mode"),
    SettingDef("datafusion.execution.target_partitions", description = "Number of partitions for query execution. Increasing partitions can increase concurrency. Defaults to the number of CPU cores on the system"),
    SettingDef("datafusion.optimizer.max_passes", description = "Number of times that the optimizer will attempt to optimize the plan"),
    SettingDef("datafusion.optimizer.subset_repartition_threshold", description = "Partition count threshold for subset satisfaction optimization. When the current partition count is >= this threshold, DataFusion will skip repartitioning if the required partitioning expression is a subset of the current partition expression such as Hash(a) satisfies Hash(a, b). When the current partition count is < this threshold, DataFusion will repartition to increase parallelism even when subset satisfaction applies. Set to 0 to always repartition (disable subset satisfaction optimization). Set to a high value to always use subset satisfaction. Example (subset_repartition_threshold = 4): ```text     Hash([a]) satisfies Hash([a, b]) because (Hash([a, b]) is subset of Hash([a])     If current partitions (3) < threshold (4), repartition:     AggregateExec: mode=FinalPartitioned, gby=[a, b], aggr=[SUM(x)]       RepartitionExec: partitioning=Hash([a, b], 8), input_partitions=3         AggregateExec: mode=Partial, gby=[a, b], aggr=[SUM(x)]           DataSourceExec: file_groups={...}, output_partitioning=Hash([a], 3)     If current partitions (8) >= threshold (4), use subset satisfaction:     AggregateExec: mode=SinglePartitioned, gby=[a, b], aggr=[SUM(x)]       DataSourceExec: file_groups={...}, output_partitioning=Hash([a], 8) ```"),
    SettingDef("datafusion.spark.map_key_dedup_policy", description = "Policy for handling duplicate keys in Spark-compatible map-construction functions (`map_from_arrays`, `map_from_entries`, `str_to_map`). Mirrors Spark's [`spark.sql.mapKeyDedupPolicy`](https://github.com/apache/spark/blob/cf3a34e19dfcf70e2d679217ff1ba21302212472/sql/catalyst/src/main/scala/org/apache/spark/sql/internal/SQLConf.scala#L4961): - `EXCEPTION` (default): raise `[DUPLICATED_MAP_KEY]` at runtime on any duplicate key. - `LAST_WIN`: keep the last occurrence of each duplicate key. Values are case-insensitive."),
    SettingDef("datafusion.execution.spill_compression", description = "Sets the compression codec used when spilling data to disk. Since datafusion writes spill files using the Arrow IPC Stream format, only codecs supported by the Arrow IPC Stream Writer are allowed. Valid values are: uncompressed, lz4_frame, zstd. Note: lz4_frame offers faster (de)compression, but typically results in larger spill files. In contrast, zstd achieves higher compression ratios at the cost of slower (de)compression speed."),
    SettingDef("datafusion.optimizer.allow_symmetric_joins_without_pruning", description = "Should DataFusion allow symmetric hash joins for unbounded data sources even when its inputs do not have any ordering or filtering If the flag is not enabled, the SymmetricHashJoin operator will be unable to prune its internal buffers, resulting in certain join types - such as Full, Left, LeftAnti, LeftSemi, Right, RightAnti, and RightSemi - being produced only at the end of the execution. This is not typical in stream processing. Additionally, without proper design for long runner execution, all types of joins may encounter out-of-memory errors."),
    SettingDef("datafusion.execution.collect_statistics", description = "Should DataFusion collect statistics when first creating a table. Has no effect after the table is created. Defaults to true."),
)

private fun datafusionSettings2(): List<SettingDef> = listOf(
    SettingDef("datafusion.execution.enforce_batch_size_in_joins", description = "Should DataFusion enforce batch size in joins or not. By default, DataFusion will not enforce batch size in joins. Enforcing batch size in joins can reduce memory usage when joining large tables with a highly-selective join filter, but is also slightly slower."),
    SettingDef("datafusion.optimizer.repartition_sorts", description = "Should DataFusion execute sorts in a per-partition fashion and merge afterwards instead of coalescing first and sorting globally. With this flag is enabled, plans in the form below ```text      \"SortExec: [a@0 ASC]\",      \"  CoalescePartitionsExec\",      \"    RepartitionExec: partitioning=RoundRobinBatch(8), input_partitions=1\", ``` would turn into the plan below which performs better in multithreaded environments ```text      \"SortPreservingMergeExec: [a@0 ASC]\",      \"  SortExec: [a@0 ASC]\",      \"    RepartitionExec: partitioning=RoundRobinBatch(8), input_partitions=1\", ```"),
    SettingDef("datafusion.execution.keep_partition_by_columns", description = "Should DataFusion keep the columns used for partition_by in the output RecordBatches"),
    SettingDef("datafusion.catalog.information_schema", description = "Should DataFusion provide access to `information_schema` virtual tables for displaying schema information"),
    SettingDef("datafusion.optimizer.repartition_aggregations", description = "Should DataFusion repartition data using the aggregate keys to execute aggregates in parallel using the provided `target_partitions` level"),
    SettingDef("datafusion.optimizer.repartition_joins", description = "Should DataFusion repartition data using the join keys to execute joins in parallel using the provided `target_partitions` level"),
    SettingDef("datafusion.optimizer.repartition_windows", description = "Should DataFusion repartition data using the partitions keys to execute window functions in parallel using the provided `target_partitions` level"),
    SettingDef("datafusion.execution.enable_recursive_ctes", description = "Should DataFusion support recursive CTEs"),
    SettingDef("datafusion.execution.use_row_number_estimates_to_optimize_partitioning", description = "Should DataFusion use row number estimates at the input to decide whether increasing parallelism is beneficial or not. By default, only exact row numbers (not estimates) are used for this decision. Setting this flag to `true` will likely produce better plans. if the source of statistics is accurate. We plan to make this the default in the future."),
    SettingDef("datafusion.execution.listing_table_factory_infer_partitions", description = "Should a `ListingTable` created through the `ListingTableFactory` infer table partitions from Hive compliant directories. Defaults to true (partition columns are inferred and will be represented in the table schema)."),
    SettingDef("datafusion.execution.listing_table_ignore_subdirectory", description = "Should sub directories be ignored when scanning directories for data files. Defaults to true (ignores subdirectories), consistent with Hive. Note that this setting does not affect reading partitioned tables (e.g. `/table/year=2021/month=01/data.parquet`)."),
    SettingDef("datafusion.format.types_info", description = "Show types in visual representation batches"),
    SettingDef("datafusion.execution.objectstore_writer_buffer_size", description = "Size (bytes) of data buffer DataFusion uses when writing output files. This affects the size of the data chunks that are uploaded to remote object stores (e.g. AWS S3). If very large (>= 100 GiB) output files are being written, it may be necessary to increase this size to avoid errors from the remote end point."),
    SettingDef("datafusion.sql_parser.default_null_ordering", description = "Specifies the default null ordering for query results. There are 4 options: - `nulls_max`: Nulls appear last in ascending order. - `nulls_min`: Nulls appear first in ascending order. - `nulls_first`: Nulls always be first in any order. - `nulls_last`: Nulls always be last in any order. By default, `nulls_max` is used to follow Postgres's behavior. postgres rule: <https://www.postgresql.org/docs/current/queries-order.html>"),
    SettingDef("datafusion.sql_parser.recursion_limit", description = "Specifies the recursion depth limit when parsing complex SQL Queries"),
    SettingDef("datafusion.execution.sort_spill_reservation_bytes", description = "Specifies the reserved memory for each spillable sort operation to facilitate an in-memory merge. When a sort operation spills to disk, the in-memory data must be sorted and merged before being written to a file. This setting reserves a specific amount of memory for that in-memory sort/merge process. Note: This setting is irrelevant if the sort operation cannot spill (i.e., if there's no `DiskManager` configured)."),
    SettingDef("datafusion.catalog.newlines_in_values", description = "Specifies whether newlines in (quoted) CSV values are supported. This is the default value for `format.newlines_in_values` for `CREATE EXTERNAL TABLE` if not specified explicitly in the statement. Parsing newlines in quoted values may be affected by execution behaviour such as parallel file scanning. Setting this to `true` ensures that newlines in values are parsed successfully, which may reduce performance."),
    SettingDef("datafusion.runtime.list_files_cache_ttl", description = "TTL (time-to-live) of the entries in the list file cache. Supports units m (minutes), and s (seconds). Example: '2m' for 2 minutes."),
    SettingDef("datafusion.execution.soft_max_rows_per_output_file", description = "Target number of rows in output files when writing multiple. This is a soft max, so it can be exceeded slightly. There also will be one file smaller than the limit if the total number of rows written is not roughly divisible by the soft max"),
    SettingDef("datafusion.execution.enable_migration_aggregate", description = "Temporary switch for aggregate stream implementations that are being migrated from `GroupedHashAggregateStream`. When set to true, DataFusion tries the migrated implementations when their preconditions are satisfied. When set to false, grouped aggregation falls back to `GroupedHashAggregateStream`. This option will be removed after the migration is finished. See <https://github.com/apache/datafusion/issues/22710> for details."),
    SettingDef("datafusion.catalog.default_catalog", description = "The default catalog name - this impacts what SQL queries use if not specified"),
    SettingDef("datafusion.optimizer.default_filter_selectivity", description = "The default filter selectivity used by Filter Statistics when an exact selectivity cannot be determined. Valid values are between 0 (no selectivity) and 100 (all rows are selected)."),
    SettingDef("datafusion.catalog.default_schema", description = "The default schema name - this impacts what SQL queries use if not specified"),
    SettingDef("datafusion.execution.time_zone", description = "The default time zone Some functions, e.g. `now` return timestamps in this time zone"),
    SettingDef("datafusion.optimizer.hash_join_single_partition_threshold", description = "The maximum estimated size in bytes for one input side of a HashJoin will be collected into a single partition"),
    SettingDef("datafusion.optimizer.hash_join_single_partition_threshold_rows", description = "The maximum estimated size in rows for one input side of a HashJoin will be collected into a single partition"),
    SettingDef("datafusion.execution.perfect_hash_join_min_key_density", description = "The minimum required density of join keys on the build side to consider a perfect hash join (see `HashJoinExec` for more details). Density is calculated as: `(number of rows) / (max_key - min_key + 1)`. A perfect hash join may be used if the actual key density > this value. Currently only supports cases where build_side.num_rows() < u32::MAX. Support for build_side.num_rows() >= u32::MAX will be added in the future."),
    SettingDef("datafusion.runtime.temp_directory", description = "The path to the temporary file directory."),
    SettingDef("datafusion.execution.max_buffered_batches_per_output_file", description = "This is the maximum number of RecordBatches buffered for each output file being worked. Higher values can potentially give faster write performance at the cost of higher peak memory consumption. This budget is split evenly between two independent points in the write pipeline (see the demuxer diagram in #7791): how many files can be in flight from the demuxer to a writer task, and how many RecordBatches are buffered for a single file's writer. Must be at least 2 so each half gets at least 1 unit of buffering - 0 or 1 would leave one side with a zero-capacity channel and panic at write time."),
    SettingDef("datafusion.format.time_format", description = "Time format for time arrays"),
    SettingDef("datafusion.format.timestamp_format", description = "Timestamp format for timestamp arrays"),
    SettingDef("datafusion.format.timestamp_tz_format", description = "Timestamp format for timestamp with timezone arrays. When `None`, ISO 8601 format is used."),
    SettingDef("datafusion.catalog.format", description = "Type of `TableProvider` to use when loading `default` schema"),
    SettingDef("datafusion.explain.analyze_level", description = "Verbosity level for \"EXPLAIN ANALYZE\". Default is \"dev\" \"summary\" shows common metrics for high-level insights. \"dev\" provides deep operator-level introspection for developers."),
    SettingDef("datafusion.execution.enable_file_stream_work_stealing", description = "When `true` (the default), DataFusion's built-in file scans dynamically rebalance files across partitions at query execution time: a partition that goes idle reads files (or byte-range morsels) originally assigned to a sibling partition, which keeps all partitions busy in a single process. Executors that depend on the plan-time partition assignment — such as Ballista and datafusion-distributed, which run each partition as an isolated task and never poll the siblings — should set this to `false` so each partition reads only its own file group and no runtime reassignment occurs."),
    SettingDef("datafusion.optimizer.repartition_file_scans", description = "When set to `true`, datasource partitions will be repartitioned to achieve maximum parallelism. This applies to both in-memory partitions and FileSource's file groups (1 group is 1 partition). For FileSources, only Parquet and CSV formats are currently supported. If set to `true` for a FileSource, all files will be repartitioned evenly (i.e., a single large file might be partitioned into smaller chunks) for parallel scanning. If set to `false` for a FileSource, different files will be read in parallel, but repartitioning won't happen within a single file. If set to `true` for an in-memory source, all memtable's partitions will have their batches repartitioned evenly to the desired number of `target_partitions`. Repartitioning can change the total number of partitions and batches per partition, but does not slice the initial record tables provided to the MemTable on creation."),
    SettingDef("datafusion.optimizer.enable_dynamic_filter_pushdown", description = "When set to true attempts to push down dynamic filters generated by operators (TopK, Join & Aggregate) into the file scan phase. For example, for a query such as `SELECT * FROM t ORDER BY timestamp DESC LIMIT 10`, the optimizer will attempt to push down the current top 10 timestamps that the TopK operator references into the file scans. This means that if we already have 10 timestamps in the year 2025 any files that only have timestamps in the year 2024 can be skipped / pruned at various stages in the scan. The config will suppress `enable_join_dynamic_filter_pushdown`, `enable_topk_dynamic_filter_pushdown` & `enable_aggregate_dynamic_filter_pushdown` So if you disable `enable_topk_dynamic_filter_pushdown`, then enable `enable_dynamic_filter_pushdown`, the `enable_topk_dynamic_filter_pushdown` will be overridden."),
    SettingDef("datafusion.sql_parser.enable_subquery_sort_elimination", description = "When set to true, DataFusion may remove `ORDER BY` clauses from subqueries or CTEs during SQL planning when their ordering cannot affect the result, such as when no `LIMIT` or other order-sensitive operator depends on them. Disable this option to preserve explicit subquery ordering in the planned query."),
    SettingDef("datafusion.sql_parser.enable_ident_normalization", description = "When set to true, SQL parser will normalize ident (convert ident to lowercase when not quoted)"),
    SettingDef("datafusion.sql_parser.enable_options_value_normalization", description = "When set to true, SQL parser will normalize options value (convert value to lowercase). Note that this option is ignored and will be removed in the future. All case-insensitive values are normalized automatically."),
)

private fun datafusionSettings3(): List<SettingDef> = listOf(
    SettingDef("datafusion.sql_parser.parse_float_as_decimal", description = "When set to true, SQL parser will parse float as decimal type"),
    SettingDef("datafusion.optimizer.expand_views_at_output", description = "When set to true, if the returned type is a view type then the output will be coerced to a non-view. Coerces `Utf8View` to `LargeUtf8`, and `BinaryView` to `LargeBinary`."),
    SettingDef("datafusion.optimizer.enable_piecewise_merge_join", description = "When set to true, piecewise merge join is enabled. PiecewiseMergeJoin is currently experimental. Physical planner will opt for PiecewiseMergeJoin when there is only one range filter."),
    SettingDef("datafusion.execution.coalesce_batches", description = "When set to true, record batches will be examined between each operator and small batches will be coalesced into larger batches. This is helpful when there are highly selective filters or joins that could produce tiny output batches. The target batch size is determined by the configuration setting"),
    SettingDef("datafusion.execution.skip_physical_aggregate_schema_check", description = "When set to true, skips verifying that the schema produced by planning the input of `LogicalPlan::Aggregate` exactly matches the schema of the input plan. When set to false, if the schema does not match exactly (including nullability and metadata), a planning error will be raised. This is used to workaround bugs in the planner that are now caught by the new schema verification step."),
    SettingDef("datafusion.explain.logical_plan_only", description = "When set to true, the explain statement will only print logical plans"),
    SettingDef("datafusion.explain.physical_plan_only", description = "When set to true, the explain statement will only print physical plans"),
    SettingDef("datafusion.explain.show_statistics", description = "When set to true, the explain statement will print operator statistics for physical plans"),
    SettingDef("datafusion.explain.show_schema", description = "When set to true, the explain statement will print schema information"),
    SettingDef("datafusion.explain.show_sizes", description = "When set to true, the explain statement will print the partition sizes"),
    SettingDef("datafusion.optimizer.enable_unions_to_filter", description = "When set to true, the logical optimizer will rewrite `UNION DISTINCT` branches that read from the same source and differ only by filter predicates into a single branch with a combined filter. This optimization is conservative and only applies when the branches share the same source and compatible wrapper nodes such as identical projections or aliases."),
    SettingDef("datafusion.optimizer.skip_failed_rules", description = "When set to true, the logical plan optimizer will produce warning messages if any optimization rules produce errors and then proceed to the next rule. When set to false, any rules that produce errors will cause the query to fail"),
    SettingDef("datafusion.optimizer.enable_topk_aggregation", description = "When set to true, the optimizer will attempt to perform limit operations during aggregations, if possible"),
    SettingDef("datafusion.optimizer.enable_aggregate_dynamic_filter_pushdown", description = "When set to true, the optimizer will attempt to push down Aggregate dynamic filters into the file scan phase."),
    SettingDef("datafusion.optimizer.enable_join_dynamic_filter_pushdown", description = "When set to true, the optimizer will attempt to push down Join dynamic filters into the file scan phase."),
    SettingDef("datafusion.optimizer.enable_topk_dynamic_filter_pushdown", description = "When set to true, the optimizer will attempt to push down TopK dynamic filters into the file scan phase."),
    SettingDef("datafusion.optimizer.enable_window_limits", description = "When set to true, the optimizer will attempt to push limit operations past window functions, if possible"),
    SettingDef("datafusion.optimizer.enable_leaf_expression_pushdown", description = "When set to true, the optimizer will extract leaf expressions (such as `get_field`) from filter/sort/join nodes into projections closer to the leaf table scans, and push those projections down towards the leaf nodes."),
    SettingDef("datafusion.optimizer.filter_null_join_keys", description = "When set to true, the optimizer will insert filters before a join between a nullable and non-nullable column to filter out nulls on the nullable side. This filter can add additional overhead when the file format does not fully support predicate push down."),
    SettingDef("datafusion.optimizer.prefer_existing_union", description = "When set to true, the optimizer will not attempt to convert Union to Interleave"),
    SettingDef("datafusion.optimizer.enable_topk_repartition", description = "When set to true, the optimizer will push TopK (Sort with fetch) below hash repartition when the partition key is a prefix of the sort key, reducing data volume before the shuffle."),
    SettingDef("datafusion.optimizer.enable_distinct_aggregation_soft_limit", description = "When set to true, the optimizer will push a limit operation into grouped aggregations which have no aggregate expressions, as a soft limit, emitting groups once the limit is reached, before all rows in the group are read."),
    SettingDef("datafusion.optimizer.enable_window_topn", description = "When set to true, the optimizer will replace Filter(rn<=K) → Window(ROW_NUMBER) → Sort patterns with a PartitionedTopKExec that maintains per-partition heaps, avoiding a full sort of the input. When the window partition key has low cardinality, enabling this optimization can improve performance. However, for high cardinality keys, it may cause regressions in both memory usage and runtime."),
    SettingDef("datafusion.optimizer.join_reordering", description = "When set to true, the physical plan optimizer may swap join inputs based on statistics. When set to false, statistics-driven join input reordering is disabled and the original join order in the query is used."),
    SettingDef("datafusion.optimizer.use_statistics_registry", description = "When set to true, the physical plan optimizer uses the pluggable `StatisticsRegistry` for statistics propagation across operators. This enables more accurate cardinality estimates compared to each operator's built-in `partition_statistics`."),
    SettingDef("datafusion.optimizer.prefer_hash_join", description = "When set to true, the physical plan optimizer will prefer HashJoin over SortMergeJoin. HashJoin can work more efficiently than SortMergeJoin but consumes more memory"),
    SettingDef("datafusion.optimizer.top_down_join_key_reordering", description = "When set to true, the physical plan optimizer will run a top down process to reorder the join keys"),
    SettingDef("datafusion.optimizer.enable_round_robin_repartition", description = "When set to true, the physical plan optimizer will try to add round robin repartitioning to increase parallelism to leverage more CPU cores"),
    SettingDef("datafusion.sql_parser.collect_spans", description = "When set to true, the source locations relative to the original SQL query (i.e. [`Span`](https://docs.rs/sqlparser/latest/sqlparser/tokenizer/struct.Span.html)) will be collected and recorded in the logical plan nodes."),
    SettingDef("datafusion.optimizer.enable_physical_uncorrelated_scalar_subquery", description = "When set to true, uncorrelated scalar subqueries are left in the logical plan and executed by `ScalarSubqueryExec` during physical execution. When set to false, all scalar subqueries (including uncorrelated ones) are rewritten to left joins by the `ScalarSubqueryToJoin` optimizer rule. Note disabling this option is not recommended. It restores pre <https://github.com/apache/datafusion/pull/21240> behavior, which silently produces incorrect results for multi-row subqueries and does not support scalar subqueries in ORDER BY / JOIN ON / aggregate-function arguments. This option is intended as a temporary escape hatch for distributed execution frameworks and is planned to be removed in a future DataFusion release."),
    SettingDef("datafusion.execution.sort_in_place_threshold_bytes", description = "When sorting, below what size should data be concatenated and sorted in a single RecordBatch rather than sorted in batches and merged."),
    SettingDef("datafusion.optimizer.prefer_existing_sort", description = "When true, DataFusion will opportunistically remove sorts when the data is already sorted, (i.e. setting `preserve_order` to true on `RepartitionExec`  and using `SortPreservingMergeExec`) When false, DataFusion will maximize plan parallelism using `RepartitionExec` even if this requires subsequently resorting data using a `SortExec`."),
    SettingDef("datafusion.catalog.create_default_catalog_and_schema", description = "Whether the default catalog and schema should be created automatically."),
    SettingDef("datafusion.execution.enable_ansi_mode", description = "Whether to enable ANSI SQL mode. The flag is experimental and relevant only for DataFusion Spark built-in functions When `enable_ansi_mode` is set to `true`, the query engine follows ANSI SQL semantics for expressions, casting, and error handling. This means: - **Strict type coercion rules:** implicit casts between incompatible types are disallowed. - **Standard SQL arithmetic behavior:** operations such as division by zero,   numeric overflow, or invalid casts raise runtime errors rather than returning   `NULL` or adjusted values. - **Consistent ANSI behavior** for string concatenation, comparisons, and `NULL` handling. When `enable_ansi_mode` is `false` (the default), the engine uses a more permissive, non-ANSI mode designed for user convenience and backward compatibility. In this mode: - Implicit casts between types are allowed (e.g., string to integer when possible). - Arithmetic operations are more lenient — for example, `abs()` on the minimum   representable integer value returns the input value instead of raising overflow. - Division by zero or invalid casts may return `NULL` instead of failing. # Default `false` — ANSI SQL mode is disabled by default."),
    SettingDef("datafusion.explain.analyze_categories", description = "Which metric categories to include in \"EXPLAIN ANALYZE\" output. Comma-separated list of: \"rows\", \"bytes\", \"timing\", \"uncategorized\". Use \"none\" to show plan structure only, or \"all\" (default) to show everything. Metrics without a declared category are treated as \"uncategorized\"."),
)

